#include <stdint.h>
#include <stddef.h>
extern uintptr_t такта_нокта(uintptr_t,uintptr_t,uintptr_t),такта_Терминал(uintptr_t);
extern void Терминал_глиф(unsigned,unsigned,unsigned,unsigned,unsigned);
extern void *memset(void *,int,size_t);
typedef struct { int категория_VALUE,부모항목,X_координатасы,세로좌표,너비값,높이값,보이는지,кулидарәле_план,план_политика;unsigned Mäten[128],озынлык_VALUE; } виджет_халәт;
static виджет_халәт 요소들[4][32];
static int Тупланылган[4],вакыйга_Исемлек[4][16];static unsigned 첫항목[4],кертү_COUNT[4],부호없는결과[4],긴부호없는값[4];
static void вакыйга(int биләүче_объект,int VALUE){if(кертү_COUNT[биләүче_объект]<16){вакыйга_Исемлек[биләүче_объект][(첫항목[биләүче_объект]+кертү_COUNT[биләүче_объект])%16]=VALUE;кертү_COUNT[биләүче_объект]++;}}
static виджет_халәт *элемент_VALUE(int биләүче_объект,int күрсәткеч_VALUE){return биләүче_объект>=0&&биләүче_объект<4&&күрсәткеч_VALUE>0&&күрсәткеч_VALUE<=32&&요소들[биләүче_объект][күрсәткеч_VALUE-1].категория_VALUE?&요소들[биләүче_объект][күрсәткеч_VALUE-1]:0;}
static void 사각영역(int X_координатасы,int 세로좌표,int 너비값,int 높이값,unsigned 색상){보드사각그림(X_координатасы,세로좌표,너비값,높이값,색상);}
int 화면보임(int биләүче_объект){if(биләүче_объект<0||биләүче_объект>=4)return 0;for(int 순번=0;순번<32;순번++)if(요소들[биләүче_объект][순번].категория_VALUE==1&&요소들[биләүче_объект][순번].보이는지)return 1;return 0;}
void 화면초기화(int биләүче_объект){memset(요소들[биләүче_объект],0,sizeof(요소들[биләүче_объект]));кертү_COUNT[биләүче_объект]=첫항목[биләүче_объект]=Тупланылган[биләүче_объект]=긴부호없는값[биләүче_объект]=0;}
static void урнаштыру(int биләүче_объект,виджет_халәт *너비값,int *X_координатасы,int *세로좌표){*X_координатасы=너비값->X_координатасы;*세로좌표=너비값->세로좌표;int мәгълүмат_урнаштыру=너비값->부모항목;for(int элемент_COUNT=0;мәгълүмат_урнаштыру&&элемент_COUNT<32;элемент_COUNT++){виджет_халәт *위쪽=элемент_VALUE(биләүче_объект,мәгълүмат_урнаштыру);if(!위쪽)break;*X_координатасы+=위쪽->X_координатасы;*세로좌표+=위쪽->세로좌표+(위쪽->категория_VALUE==1?30:0);мәгълүмат_урнаштыру=위쪽->부모항목;}}
static int 표시됨(int биләүче_объект,виджет_халәт *너비값){for(int элемент_COUNT=0;элемент_COUNT<32;элемент_COUNT++){if(!너비값->보이는지)return 0;if(너비값->категория_VALUE==1)return 1;너비값=элемент_VALUE(биләүче_объект,너비값->부모항목);if(!너비값)return 0;}return 0;}
static void Mäten(int X_координатасы,int 세로좌표,виджет_халәт *너비값,int 최대값,unsigned 색상,unsigned 배경색){int 현재위치=0;for(unsigned 순번=0;순번<너비값->озынлык_VALUE;순번++){unsigned символ_кодлау=너비값->Mäten[순번],너비=символ_кодлау>=256?16:8;if(현재위치+(int)너비>최대값)break;Терминал_глиф(X_координатасы+현재위치,세로좌표,символ_кодлау,색상,배경색);현재위치+=너비;}}
void 화면다시그림(int биләүче_объект){
    if(!화면보임(биләүче_объект))return;
    for(int 처리차례=1;처리차례<=5;처리차례++)for(int 순번=0;순번<32;순번++){
        виджет_халәт *너비값=&요소들[биләүче_объект][순번];if(너비값->категория_VALUE!=처리차례||!표시됨(биләүче_объект,너비값))continue;int X_координатасы,세로좌표;урнаштыру(биләүче_объект,너비값,&X_координатасы,&세로좌표);
        if(처리차례==1){사각영역(X_координатасы,세로좌표,너비값->너비값,너비값->높이값,0xeee9e0);사각영역(X_координатасы,세로좌표,너비값->너비값,30,0x905020);Mäten(X_координатасы+10,세로좌표+7,너비값,너비값->너비값-50,0xffffff,0x905020);사각영역(X_координатасы+너비값->너비값-28,세로좌표+4,24,22,0x5555b8);Терминал_глиф(X_координатасы+너비값->너비값-20,세로좌표+7,'X',0xffffff,0x5555b8);}
        if(처리차례==2)사각영역(X_координатасы,세로좌표,너비값->너비값,너비값->높이값,0xeee9e0);
        if(처리차례>=3){unsigned 배경색=처리차례==4?0xc0ab86:처리차례==5?0xffffff:0xeee9e0;if(처리차례!=3)사각영역(X_координатасы,세로좌표,너비값->너비값,너비값->높이값,배경색);Mäten(X_координатасы+4,세로좌표+4,너비값,너비값->너비값-8,0x201a15,배경색);if(처리차례==5&&Тупланылган[биләүче_объект]==순번+1)사각영역(X_координатасы,세로좌표+너비값->높이값-2,너비값->너비값,2,0x905020);}
    }
}
int 화면덮음(int биләүче_объект,int X_координатасы,int 세로좌표){
    if(!화면보임(биләүче_объект))return 0;
    for(int 순번=0;순번<32;순번++){
        виджет_халәт *тәрәз=&요소들[биләүче_объект][순번];
        if(тәрәз->категория_VALUE==1&&тәрәз->보이는지&&X_координатасы>=тәрәз->X_координатасы&&세로좌표>=тәрәз->세로좌표&&
           X_координатасы<тәрәз->X_координатасы+тәрәз->너비값&&세로좌표<тәрәз->세로좌표+тәрәз->높이값)return 1;
    }return 0;
}
int 화면가리킴(int биләүче_объект,unsigned 눌림,int X_координатасы,int 세로좌표){
    if(!화면보임(биләүче_объект))return 0;
    if(눌림&1)for(int 순번=31;순번>=0;순번--){виджет_халәт *너비값=&요소들[биләүче_объект][순번];if(!너비값->категория_VALUE||!표시됨(биләүче_объект,너비값))continue;int 창가로,창세로;урнаштыру(биләүче_объект,너비값,&창가로,&창세로);
        if(X_координатасы<창가로||세로좌표<창세로||X_координатасы>=창가로+너비값->너비값||세로좌표>=창세로+너비값->높이값)continue;
        if(너비값->категория_VALUE==1&&세로좌표<창세로+30&&X_координатасы>=창가로+너비값->너비값-28){if(너비값->план_политика!=0)너비값->보이는지=0;вакыйга(биләүче_объект,0x10000+순번+1);такта_Терминал(3);return 1;}
        if(너비값->категория_VALUE==4){вакыйга(биләүче_объект,순번+1);return 1;}if(너비값->категория_VALUE==5){Тупланылган[биләүче_объект]=순번+1;такта_Терминал(3);return 1;}
        if(너비값->категория_VALUE==1)return 1;
    }return 0;
}
void 화면누름(int биләүче_объект,unsigned SECOND_VALUE){
    виджет_халәт *너비값=элемент_VALUE(биләүче_объект,Тупланылган[биләүче_объект]);if(!너비값||너비값->категория_VALUE!=5)return;
    if(SECOND_VALUE==13||SECOND_VALUE==10){вакыйга(биләүче_объект,Тупланылган[биләүче_объект]);return;}
    if(SECOND_VALUE==8||SECOND_VALUE==127){if(너비값->озынлык_VALUE)너비값->озынлык_VALUE--;긴부호없는값[биләүче_объект]=0;}
    else{
        unsigned символ_кодлау=SECOND_VALUE;
        if(긴부호없는값[биләүче_объект]){if((SECOND_VALUE&192)!=128){긴부호없는값[биләүче_объект]=0;return;}부호없는결과[биләүче_объект]=(부호없는결과[биләүче_объект]<<6)|(SECOND_VALUE&63);if(--긴부호없는값[биләүче_объект])return;символ_кодлау=부호없는결과[биләүче_объект];}
        else if(SECOND_VALUE>=0xc2&&SECOND_VALUE<=0xf4){긴부호없는값[биләүче_объект]=SECOND_VALUE<0xe0?1:SECOND_VALUE<0xf0?2:3;부호없는결과[биләүче_объект]=SECOND_VALUE&((1u<<(6-긴부호없는값[биләүче_объект]))-1);return;}
        else if(SECOND_VALUE<32||SECOND_VALUE>=128)return;
        if(символ_кодлау>0x10ffff||(символ_кодлау>=0xd800&&символ_кодлау<=0xdfff))return;if(너비값->озынлык_VALUE<127)너비값->Mäten[너비값->озынлык_VALUE++]=символ_кодлау;
    }
    такта_Терминал(3);
}
int 화면호출(int биләүче_объект,unsigned Гамәл,int күрсәткеч_VALUE,int 첫째값,int SECOND_VALUE,int символ_коды,int күчерү_урыны_мәгълүмат){
    if(биләүче_объект<0||биләүче_объект>=4)return -22;виджет_халәт *너비값=элемент_VALUE(биләүче_объект,күрсәткеч_VALUE);
    if(Гамәл==0){if(күрсәткеч_VALUE<1||күрсәткеч_VALUE>5)return -22;for(int 순번=0;순번<32;순번++)if(요소들[биләүче_объект][순번].категория_VALUE==0){너비값=&요소들[биләүче_объект][순번];memset(너비값,0,sizeof(*너비값));너비값->категория_VALUE=күрсәткеч_VALUE;너비값->보이는지=күрсәткеч_VALUE!=1;너비값->너비값=күрсәткеч_VALUE==1?380:220;너비값->높이값=күрсәткеч_VALUE==1?240:28;너비값->план_политика=1;너비값->X_координатасы=күрсәткеч_VALUE==1?130:16;너비값->세로좌표=күрсәткеч_VALUE==1?110:16;return 순번+1;}return -28;}
    if(Гамәл==5){if(!кертү_COUNT[биләүче_объект])return 0;int 반환값=вакыйга_Исемлек[биләүче_объект][첫항목[биләүче_объект]];첫항목[биләүче_объект]=(첫항목[биләүче_объект]+1)%16;кертү_COUNT[биләүче_объект]--;return 반환값;}
    if(Гамәл==6)return 화면보임(биләүче_объект);
    if(!너비값)return -9;
    int 이전표시=표시됨(биләүче_объект,너비값);
    if(Гамәл==1){int 바탕너비=보드화면너비(),바탕높이=보드화면높이();if(첫째값<0||SECOND_VALUE<0||символ_коды<1||күчерү_урыны_мәгълүмат<1||첫째값>바탕너비||SECOND_VALUE>바탕높이||символ_коды>바탕너비-첫째값||күчерү_урыны_мәгълүмат>바탕높이-SECOND_VALUE)return -22;너비값->X_координатасы=첫째값;너비값->세로좌표=SECOND_VALUE;너비값->너비값=символ_коды;너비값->높이값=күчерү_урыны_мәгълүмат;너비값->кулидарәле_план=1;}
    else if(Гамәл==2){виджет_халәт *бала_элемент=элемент_VALUE(биләүче_объект,첫째값);if(!бала_элемент||бала_элемент==너비값||бала_элемент->категория_VALUE==1)return -22;int мәгълүмат_урнаштыру=күрсәткеч_VALUE;for(int 깊이=0;мәгълүмат_урнаштыру&&깊이<32;깊이++){if(мәгълүмат_урнаштыру==첫째값)return -22;виджет_халәт *위쪽=элемент_VALUE(биләүче_объект,мәгълүмат_урнаштыру);мәгълүмат_урнаштыру=위쪽?위쪽->부모항목:0;}бала_элемент->부모항목=күрсәткеч_VALUE;if(!бала_элемент->кулидарәле_план){int 형제요소=0;for(int 순번=0;순번<32;순번++)if(&요소들[биләүче_объект][순번]!=бала_элемент&&요소들[биләүче_объект][순번].부모항목==күрсәткеч_VALUE)형제요소++;бала_элемент->세로좌표=16+형제요소*36;}}
    else if(Гамәл==3)너비값->보이는지=첫째값!=0;
    else if(Гамәл==4)너비값->보이는지=0;
    else if(Гамәл==7)너비값->план_политика=첫째값;
    else if(Гамәл==8)return 너비값->озынлык_VALUE;
    else if(Гамәл==9)return 첫째값>=0&&(unsigned)첫째값<너비값->озынлык_VALUE?너비값->Mäten[첫째값]:-22;
    else return -22;
    if(이전표시||표시됨(биләүче_объект,너비값))такта_Терминал(3);return 0;
}
int 화면글(int биләүче_объект,int күрсәткеч_VALUE,const uint32_t *мәгълүмат,unsigned элемент_COUNT){виджет_халәт *너비값=элемент_VALUE(биләүче_объект,күрсәткеч_VALUE);if(!너비값)return -9;if(элемент_COUNT>127)return -22;for(unsigned 순번=0;순번<элемент_COUNT;순번++){unsigned символ_кодлау=мәгълүмат[순번];if(символ_кодлау>0x10ffff||(символ_кодлау>=0xd800&&символ_кодлау<=0xdfff))return -22;}for(unsigned 순번=0;순번<элемент_COUNT;순번++)너비값->Mäten[순번]=мәгълүмат[순번];너비값->озынлык_VALUE=элемент_COUNT;if(표시됨(биләүче_объект,너비값))такта_Терминал(3);return 0;}
